hooks.command:
[ -n "${GITHUB_ACTIONS:-}" ] && exit 0
r() { printf '%s' "{\"hookSpecificOutput\":{\"hookEventName\":\"PreToolUse\",\"permissionDecision\":\"$1\",\"permissionDecisionReason\":\"$2\"}}"; exit 0; }
c=$(jq -r '.tool_input.command')
m() { printf '%s' "$c" | grep -Eq "$1"; }
t() { m "(^|[^[:alnum:]_.-])$1([^[:alnum:]_.-]|\$)"; }
F='(^|[[:space:]])--force(-with-lease)?([[:space:]=]|$)|(^|[[:space:]])-[[:alnum:]]*f[[:alnum:]]*([[:space:]]|$)'
m 'docs/\.env' && r deny 'docs/.env は秘密情報です。読み取り・出力・コミットのいずれも禁止です(CLAUDE.md)。パスに言及するだけのコマンドも安全側で拒否しています。'
t gh && { t merge && r deny 'マージはPOの操作です(docs/development-workflow.md 8章)。gh pr merge も gh api の .../merge も対象です。コメント本文に merge の語が含まれただけでもここに来ます。その場合は --body-file でファイル渡しにしてください。'; t api && m '(^|[[:space:]])(-X|--method|-f|-F|--raw-field|--input)([[:space:]=]|$)' && r deny 'gh api での書き込みは禁止です。読み取り以外はPOの操作です(docs/development-workflow.md 8章)。-f / -F はメソッド未指定でもPOSTになります。'; }
t git || exit 0
t push && { m "$F|[[:space:]]\+[^[:space:]]+" && r deny 'force push は禁止です(docs/development-workflow.md 8章)。--force / --force-with-lease / f を含む短オプション / + 付きリフスペックのいずれも対象です。'; }
t reset && m '(^|[[:space:]])--hard([[:space:]]|$)' && r ask '未コミットの変更が失われます。実行してよいか確認してください(docs/development-workflow.md 8章)。'
t clean && m "$F" && r ask '追跡外のファイルが削除されます。実行してよいか確認してください(docs/development-workflow.md 8章)。'
exit 0
